  "who whom whose which what where why how not no yes up down out off about after before again too both either neither everything everyone anything something using give gives").split(/\s+/));
const GENERIC = new Set(["command", "commands", "player", "players", "feature", "features", "option", "options", "thing", "things", "item", "items", "ability", "abilities", "system", "way", "ways", "kind", "type", "types
const SYN = { shift: "sneak", crouch: "sneak", sneaking: "sneak", crouching: "sneak", heal: "health", heals: "health", healing: "health", hearts: "health", heart: "health", hp: "health", cooldown: "cooldown", cooldowns: 

function stem(w) {
  let s = String(w).toLowerCase().replace(/[^a-z0-9]/g, "");
  if (SYN[s]) return SYN[s];
  if (s.length > 5 && s.endsWith("ing")) s = s.slice(0, -3);
  else if (s.length > 4 && s.endsWith("ies")) s = s.slice(0, -3) + "y";
  else if (s.length > 4 && s.endsWith("es")) s = s.slice(0, -2);
  else if (s.length > 3 && s.endsWith("s") && !s.endsWith("ss")) s = s.slice(0, -1);
  else if (s.length > 4 && s.endsWith("ed")) s = s.slice(0, -2);
  return SYN[s] || s;
}

/** Content stems of a sentence, in order, de-duplicated. */
function keywords(text, max = 6) {
  const out = [];
  for (const raw of String(text).toLowerCase().replace(/\/[a-z][\w-]*/g, " ").split(/[^a-z0-9]+/)) {
    if (raw.length < 3 || STOP.has(raw) || /^\d+$/.test(raw)) continue;
    const s = stem(raw);
    if (s.length < 3 || STOP.has(s) || GENERIC.has(s) || out.includes(s)) continue;
    out.push(s);
    if (out.length >= max) break;
  }
  return out;
}

function slug(s) { return String(s).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 48); }
function clip(s, n) { s = String(s).replace(/\s+/g, " ").trim(); return s.length > n ? s.slice(0, n - 1).trimEnd() + "…" : s; }

