//  - parseChangeContext: what the client knows about the mod a change lands on (name, next version, summary, file paths),
//    bounded and sanitised (it only feeds the "This changes your existing mod / what will be kept" lines).
//  - changeLaneDefaults: on a CHANGE request, a NEW generative lane (textures, sounds, item with abilities, menus, ...)
//    is never pre-selected unless the change text asks for it (the word rules see it). The ChunkMirror incident
//    (2026-10-12, tracker 58b): the planner turned "mob spawner" into "Item with abilities" and a Spawner Wand replaced
//    the plugin. The user can still tick the lane back on; an explicit toggle always wins.
// The build-side guards (planner lane guard on change builds, additive designer compile, regression guard vs the base
// build) belong to fix/cyrus-change-regression-guards; this file only sets the plan screen's defaults.
import { ruleNeeds } from "../planner/rules";
import type { Lane, LaneNeed } from "../planner/lanes";
import { GENERATIVE_LANES, type ChangeContext } from "./analyze";

export function parseChangeContext(raw: unknown): ChangeContext | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  const r = raw as Record<string, unknown>;
  const name = typeof r.name === "string" ? r.name.replace(/[<>\n\r]/g, " ").trim().slice(0, 60) : "";
  if (!name) return null;
  const version = typeof r.version === "number" && Number.isInteger(r.version) && r.version > 0 && r.version < 10_000 ? r.version : undefined;
  const summary = typeof r.summary === "string" ? r.summary.replace(/[<>]/g, " ").replace(/\s+/g, " ").trim().slice(0, 300) : null;
  const paths = Array.isArray(r.paths) ? r.paths.filter((p): p is string => typeof p === "string").map((p) => p.slice(0, 200)).slice(0, 200) : [];
  return { name, ...(version ? { version } : {}), summary, paths };
}

/** Lanes the planner wants for a change that its text does not ask for, and the user has not toggled themselves. */
export function changeLaneDefaults(text: string, needs: readonly LaneNeed[], toggles: Partial<Record<Lane, boolean>>, game = "minecraft"): Lane[] {
  const asked = new Set(ruleNeeds(text, game).filter((n) => n.need).map((n) => n.lane));
  return needs.filter((n) => n.need && GENERATIVE_LANES.includes(n.lane) && !asked.has(n.lane) && toggles[n.lane] === undefined).map((n) => n.lane);
}
