// ---------------------------------------------------------------------------
// Game-server grants
// ---------------------------------------------------------------------------

function perMonth(kind: "initial" | "renew", monthlyCents: number, cfg: TokenConfig): number {
  if (!(monthlyCents > 0)) return 0;
  const r = cfg.grant[kind];
  return Math.round(clamp(round5(r.base + r.perUsd * (monthlyCents / 100)), r.min, r.max));
}

export type ServerGrant = { tokens: number; initialPerMonth: number; renewPerMonth: number; months: number; expiresInDays: number };

/**
 * Tokens for a game-server purchase ("initial") or a paid renewal ("renewal").
 * `monthlyCents` = what the customer actually pays per month (after discounts, before tax).
 * A prepaid N-month term earns the per-month renewal amount for each extra month, capped.
 */
export function serverGrant(kind: "initial" | "renewal", monthlyCents: number, termMonths: number, cfg: TokenConfig): ServerGrant {
  const months = clamp(Math.round(termMonths || 1), 1, cfg.grant.termMonthsCap);
  const ini = perMonth("initial", monthlyCents, cfg);
  const ren = perMonth("renew", monthlyCents, cfg);
  const tokens = kind === "initial" ? (ini ? ini + ren * (months - 1) : 0) : ren * months;
  const expiresInDays = Math.max(cfg.grant.expiryDays, Math.round(termMonths || 1) * 31 + 30);
  return { tokens, initialPerMonth: ini, renewPerMonth: ren, months, expiresInDays };
}

/** The checkout line: "Includes N Cyrus tokens (+M every renewal)". */
export function checkoutLine(monthlyCents: number, termMonths: number, cfg: TokenConfig): { initial: number; renewal: number; text: string } | null {
  const i = serverGrant("initial", monthlyCents, termMonths, cfg);
  const r = serverGrant("renewal", monthlyCents, termMonths, cfg);
  if (!i.tokens) return null;
  return { initial: i.tokens, renewal: r.tokens, text: `Includes ${fmt(i.tokens)} Cyrus tokens (+${fmt(r.tokens)} every renewal) · Beta, Minecraft Java` };
}

export const fmt = (n: number) => Math.round(n).toLocaleString("en-US");

// ---------------------------------------------------------------------------
// Builds: estimate, reserve, settle
// ---------------------------------------------------------------------------

export function complexityOf(text: string): Complexity {
  return estimate(text, "saka").complexity;
}

export function reserveRange(model: CyrusModelId, complexity: Complexity, cfg: TokenConfig): [number, number] {
  return cfg.reserve[model]?.[complexity] ?? cfg.reserve.saka.standard;
}

/**
 * Live-test fix (C1): what a build HOLDS. The reserve table's range, raised to the planned estimate in tokens
 * (lib/cyrus/planner/estimate.ts, +20% headroom on the high end) so the real spend rarely exceeds the hold: the first
 * live Yakko build held 250 (the table's simple high) and spent 431. Without an estimate: the table, unchanged.
 */

