"use client";
// Customer app: follows a build that is still running on the project page. Polls the build API (which also syncs the
// row with the build service, exactly like the studio does), says in plain words what is happening, and refreshes the
// page when the build ends so the install panel and Test Flight appear without a manual reload.
import { useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { CYRUS_STAGES, CYRUS_STATUS_LABEL } from "@/lib/cyrus/models";
import { queueLine } from "@/lib/cyrus/builder/queue-view";
import type { MbQueue } from "@/lib/cyrus/builder/types";

const TERMINAL = new Set(["succeeded", "failed"]);
const PLAIN: Record<string, string> = {
  queued: "Waiting for a free builder. Nothing is spent until it starts.",
  planning: "Working out what your mod needs.",
  coding: "Writing the code.",
  compiling: "Turning the code into a real plugin.",
  repairing: "Fixing a small problem it found. This is normal and does not need you.",
  scanning: "Running the safety check.",
};

export function BuildFollower({ buildId, initialStatus, startedAt }: { buildId: string; initialStatus: string; startedAt: string }) {
  const router = useRouter();
  const [status, setStatus] = useState(initialStatus);
  const [error, setError] = useState<string | null>(null);
  const [lost, setLost] = useState(false);
  const [queue, setQueue] = useState<{ queuePosition?: number; queue?: MbQueue | null } | null>(null);
  const [tick, setTick] = useState(0);
  const done = useRef(false);

  useEffect(() => {
    if (TERMINAL.has(status)) return;
    let stop = false;
    const poll = async () => {
      try {
        const r = await fetch(`/api/mod-builder/builds/${encodeURIComponent(buildId)}`, { cache: "no-store" });
        if (!r.ok) throw new Error(String(r.status));
        const j = (await r.json()) as { build?: { status?: string; error?: string | null; result?: { queuePosition?: number; queue?: MbQueue | null } | null } };
        if (stop || !j.build?.status) return;
        setLost(false);
        setStatus(j.build.status);
        setQueue(j.build.result ?? null);
        if (TERMINAL.has(j.build.status)) { setError(j.build.error ?? null); if (!done.current) { done.current = true; router.refresh(); } }
      } catch { if (!stop) setLost(true); }
    };
    const t = setInterval(poll, 4000);
    const c = setInterval(() => setTick((x) => x + 1), 1000);
    void poll();
    return () => { stop = true; clearInterval(t); clearInterval(c); };
  }, [buildId, status, router]);

  void tick;
  const secs = Math.max(0, Math.round((Date.now() - new Date(startedAt).getTime()) / 1000));
  const elapsed = secs < 60 ? `${secs}s` : `${Math.floor(secs / 60)}m ${secs % 60}s`;
  const idx = CYRUS_STAGES.findIndex((s) => s.key === status);
  const failed = status === "failed";

  return (
    <div role="status" aria-live="polite" style={{ display: "grid", gap: 10 }} data-testid="build-follower">
      <div style={{ display: "flex", alignItems: "baseline", gap: 10, flexWrap: "wrap" }}>
        <b>{failed ? "This build did not finish." : status === "succeeded" ? "Your mod is ready." : status === "queued" ? queueLine(queue).label : CYRUS_STATUS_LABEL[status] ?? "Building"}</b>
