// Cyrus mod planner POLICY (pure, no model): what the planner is allowed to PROMISE. Three deterministic rules, each
// pinned by evidence, applied after the planner model / word rules and before the capability router (./decide.ts):
//   1. PLAIN BY EVIDENCE: archetypes the designer lane downgraded to a plain plugin on purpose (rc11 designStrict; eval
//      fifth1: cov-warps, cov-playtime-rewards, cov-tablist, cov-bossbar-titles). A planned design there is a lane that
//      "ships nothing" (BZ real pass 79.2%): left out up front, and the plan card says it is built as plugin code.
//   2. CORROBORATION: a designer / data pack / library lane the model asks for but no word rule supports is left out.
//      Owner batch 2026-10-14 (records.json): the model planned datapack for armor-set bonus, daily quests, potions and
//      enchantments, a designer for a fox companion, worldgen for goblins; food-potions "planned a data pack and
//      shipped none". Model confidence did not separate them (0.80-0.95), so the gate is the rules, not the number.
//   3. LIMITS: asks no lane can deliver (vanilla world edits, voice chat, ...) become a plain "cannot" note.
import type { Lane, LaneNeed } from "./lanes";
import { LANE_META } from "./lanes";

export type PlainRule = { id: string; test: RegExp; /** when this also matches, the rule does not apply */ unless?: RegExp; drop: Lane[]; reason: string };

export const PLAIN_BY_EVIDENCE: PlainRule[] = [
  {
    id: "warps", test: /\b(warps?|homes?|\/sethome|\/warp)\b/i, unless: /\b(shop|kits?|class(?:es)? selector|selector|quests?|boss|buttons?|server menu|main menu|compass|hub)\b/i, drop: ["designMenu", "designHud", "designQuest"],
    reason: "Warps and homes are built as plain plugin code: a designed menu added nothing in testing and came with an unrequested boss bar and sidebar.",
  },
  {
    id: "login-rewards", test: /\b(daily (?:login )?rewards?|login (?:rewards?|streaks?)|playtime rewards?|streaks?)\b/i, unless: /\bquests?\b|\bmissions?\b|\b(?:buttons?|server menu|main menu|compass|hub|selector)\b/i, drop: ["designMenu",
    reason: "Login streaks and playtime rewards are built as plain plugin code: a designed version added an always-on boss bar and sidebar nobody asked for.",
  },
  {
    id: "tab-list", test: /\btab ?(?:list|header|footer)\b|\bplayer list (?:header|footer)\b/i, unless: /\b(sidebar|side ?bar|scoreboard|hud|action ?bar|mana|glyphs?|icons?)\b/i, drop: ["designHud", "designMenu"],
    reason: "A tab list header and footer is built as plain plugin code (a designed HUD does not apply to it).",
  },
  {
    id: "bossbar-title", test: /\b(boss ?bars?|titles?|countdowns?)\b/i, unless: /\b(boss ?fights?|mini-?boss|bosse?s\b|boss(?! ?bars?)\b|encounters?|phases?|waves?|hud|glyphs?|icons?|mana|sidebar)\b/i, drop: ["designBoss", "designHud"],
    reason: "A boss bar or title for a countdown is built as plain plugin code (it is not a boss fight and needs no HUD design).",
  },
  {
    id: "player-shops", test: /\bplayers? (?:can |to )?(?:make|create|set ?up|open|run|build)\b[^.]{0,30}\bshops?\b|\b(?:chest ?shops?|sign ?shops?|player ?shops?)\b|\bown shops?\b/i, drop: ["designMenu"],
    reason: "Player-run shops (a sign on a chest) are built as plugin code: a designed menu fits a server-made shop, not player-made ones.",
  },
  {
    id: "bounty", test: /\bbount(?:y|ies)\b/i, unless: /\bquests?\b|\bmissions?\b/i, drop: ["designQuest"],
    reason: "A bounty system is built as plugin code: it is a money mechanic, not a quest chain.",
  },
];

/** Lanes the model can add on its own that the word rules must support (the model's confidence is not trusted for these). */
export const CORROBORATE: readonly Lane[] = ["designItem", "designMenu", "designQuest", "designBoss", "designHud", "motion", "datapack", "worldgen", "library", "itemStates", "model3d"];
/** Sound is the softest case: speculative "needs roars" is left out unless the model is sure. */
export const SOUND_MIN_CONFIDENCE = 0.85;

/** Demote the lanes the plain-by-evidence rules cover (applies to rule and model needs alike). */
export function applyPlain(needs: LaneNeed[], text: string): LaneNeed[] {
  const hit = PLAIN_BY_EVIDENCE.filter((r) => r.test.test(text) && !(r.unless && r.unless.test(text)));
  if (!hit.length) return needs;
  return needs.map((n) => {
    if (!n.need) return n;
    const r = hit.find((x) => x.drop.includes(n.lane));
    return r ? { ...n, need: false, why: "", demoted: "plain" as const, note: r.reason } : n;
  });
}

/** Leave out model-only lanes the rules do not corroborate. `rules` = the word rules' needs (after the plain demotions). */
export function applyPolicy(needs: LaneNeed[], rules: LaneNeed[], literal: ReadonlySet<Lane>): LaneNeed[] {
  const ruled = new Set(rules.filter((r) => r.need).map((r) => r.lane));
  return needs.map((n) => {
    if (!n.need || ruled.has(n.lane) || literal.has(n.lane)) return n;
    if (CORROBORATE.includes(n.lane)) return { ...n, need: false, why: "", demoted: "uncorroborated" as const, note: `${LANE_META[n.lane].label}: the request does not say this; built in plugin code if needed.` };
    if (n.lane === "sound" && n.confidence < SOUND_MIN_CONFIDENCE) return { ...n, need: false, why: "", demoted: "uncorroborated" as const, note: "Custom sounds: the request does not mention sounds." };
    return n;
  });
}

export type Limit = { id: string; test: RegExp; lane?: Lane; reason: string };
/** Asks that no lane can deliver. Shown on the plan card as "cannot be built", never planned as a lane. */
export const LIMITS: Limit[] = [
  {
    id: "vanilla-worldgen", lane: "worldgen",
    test: /\bores?\b[^.]{0,30}\bgener\w+|\bgener\w+[^.]{0,20}\bores?\b|\b(?:rarer|more|fewer|less|bigger|larger) (?:diamonds?|ores?|copper|iron|gold|emeralds?|coal|lapis|redstone)\b[^.]{0,40}\b(?:veins?|gener\w+|underground|world|caves?)\b|
    reason: "Changing how the existing world generates (ores, vanilla biomes, terrain) cannot be built: a data pack cannot edit vanilla world generation. A new biome or dimension of its own can be built.",
  },
  { id: "voice-chat", test: /\b(proximity |voice )?voice chat\b|\bmicrophone\b/i, reason: "Voice chat needs a client mod: a server plugin cannot carry audio." },
  { id: "shaders", test: /\b(shaders?|ray ?tracing|minimaps?|mini-?maps?)\b/i, reason: "Shaders and minimaps need a client mod: a server plugin cannot draw them." },
  { id: "new-block-types", test: /\b(?:brand new|entirely new|real) (?:block types?|blocks?|dimensions? types?)\b|\bnew (?:ore|block) (?:type|with its own (?:model|texture))\b/i, reason: "Genuinely new block types need a client mod; Cyrus b
];

export function limitsFor(text: string): Limit[] {
  return LIMITS.filter((l) => l.test.test(text));
}
