// Cyrus planner: LANE MEASUREMENT (pure, no model). Scores any lane selector against labelled prompts and returns per-lane
// recall/precision, a confusion table (a missed lane next to a wrongly selected one) and the misses ranked by class.
// `optional` lanes are defensible either way: never a miss, never an extra. `config` is implied by every plugin: not scored.
import { LANES, type Lane } from "./lanes";

export type MeasureCase = { id: string; set: string; text: string; need: Lane[]; optional?: Lane[]; plain?: boolean };
/** Disputed labels: these lanes are not scored for the case (neither miss nor extra). */
export type Disputes = Record<string, { lanes: Lane[] }>;
export type CaseResult = { id: string; set: string; text: string; need: Lane[]; got: Lane[]; missed: Lane[]; extra: Lane[]; exact: boolean };
export type LaneRow = { lane: Lane; expected: number; selected: number; hit: number; fp: number; recall: number | null; precision: number | null };
export type Measure = {
  set: string; cases: number; exact: number; exactPct: number | null;
  recallPct: number | null; precisionPct: number | null; wanted: number; hit: number; selected: number;
  plainCases: number; plainOver: number;
  lanes: LaneRow[]; confusions: { missed: Lane; extra: Lane; n: number }[]; results: CaseResult[];
};

const SCORED = LANES.filter((l) => l !== "config");
const pct = (a: number, b: number) => (b ? Math.round((a / b) * 1000) / 10 : null);

export function measure(set: string, cases: MeasureCase[], select: (c: MeasureCase) => Lane[], disputes: Disputes = {}): Measure {
  const lane = new Map<Lane, LaneRow>(SCORED.map((l) => [l, { lane: l, expected: 0, selected: 0, hit: 0, fp: 0, recall: null, precision: null }]));
  const conf = new Map<string, number>();
  let wanted = 0, hit = 0, selected = 0, plainCases = 0, plainOver = 0;
  const results: CaseResult[] = cases.map((c) => {
    const skip = new Set(disputes[c.id]?.lanes ?? []);
    const got = new Set(select(c).filter((l) => l !== "config" && !skip.has(l)));
    const need = new Set(c.need.filter((l) => l !== "config" && !skip.has(l)));
    // datapack is carried by the worldgen lane (toAssetsRequest turns datapack on for worldgen)
    if (need.has("datapack") && got.has("worldgen")) got.add("datapack");
    const opt = new Set(c.optional ?? []);
    const missed = [...need].filter((l) => !got.has(l));
    const extra = [...got].filter((l) => !need.has(l) && !opt.has(l));
    for (const l of need) { const r = lane.get(l)!; r.expected++; wanted++; if (got.has(l)) { r.hit++; hit++; } }
    for (const l of got) { const r = lane.get(l)!; if (!opt.has(l) || need.has(l)) { r.selected++; selected++; } if (!need.has(l) && !opt.has(l)) r.fp++; }
    for (const m of missed) for (const e of extra) conf.set(`${m}>${e}`, (conf.get(`${m}>${e}`) ?? 0) + 1);
    if (c.plain) { plainCases++; if (extra.length) plainOver++; }
    return { id: c.id, set: c.set, text: c.text, need: [...need], got: [...got], missed, extra, exact: !missed.length && !extra.length };
  });
  const rows = [...lane.values()].filter((r) => r.expected || r.selected || r.fp).map((r) => ({ ...r, recall: pct(r.hit, r.expected), precision: pct(r.hit, r.hit + r.fp) }));
