// ------------------------------------------------------------------------------------------------ CODE CORE
// Archetypes whose logic lives in Java: an instanced world per run, a roguelike run (floors, rooms, saved state).
// Mega-mod incident 2026-10-15 (the owner's "Infinite Dungeon"): the planner chose designMenu + designHud + config
// (+ worldgen) for a mod whose heart is code (a void world per run, saving and restoring the overworld state, room
// generation). A designer lane compiles the plugin from a typed spec, so that plugin would have none of it. Flag
// CYRUS_CODE_CORE (off): the designer/data-pack lanes are left out up front, the plan card says "the core is plugin
// code", and an explicit toggle still wins. Measured on the 80 real-world prompts / evalset / golden / owner batch:
// no change (the archetypes do not occur there), see CM report section 3.
export const CODE_CORE_FLAG = "CYRUS_CODE_CORE";
export const codeCoreOn = (env: Record<string, string | undefined> = process.env) => env[CODE_CORE_FLAG] === "1";

export type CodeCore = { id: string; label: string; test: RegExp; /** the lanes that cannot carry this archetype (left out) */ demote: readonly Lane[]; text: string };
const DESIGNS: readonly Lane[] = ["designItem", "designMenu", "designQuest", "designBoss", "designHud", "motion"];
export const CODE_CORE: CodeCore[] = [
  {
    id: "instanced-world", label: "an instanced world per run",
    test: /\b(?:instanced?|per[- ]run|per[- ]player|void|temporary|private|isolated) (?:world|dimension)s?\b|\bempty (?:void )?world\b|\bseparate (?:empty |void |private |new )?world\b|\bwithout touching (?:my|the|our) (?:existing |survival |main |current )?(?:world|server|map)\b/i,
    demote: [...DESIGNS, "worldgen"],
    text: "The core of this mod (a separate world for each run, saving and restoring the player's own world state, room generation) is written as plugin code. Designer lanes compile a plugin from a typed spec and would leave that out, so they are not used for it; menus, bars and bosses are written in the same code.",
  },
  {
    id: "roguelike", label: "a roguelike run",
    test: /\broguelike\b|\brogue-?lite\b|\bdungeon (?:crawler|run|mode|floors?)\b|\binfinite dungeon\b|\b\d{2,3} floors?\b|\bfloor (?:counter|number)\b|\brun seed\b|\bprocedural(?:ly)?[- ]generated (?:rooms?|dungeons?|floors?)\b/i,
    demote: [...DESIGNS, "worldgen"],
    text: "The core of this mod (the run loop, floors, rooms, saved progress) is written as plugin code. Designer lanes compile a plugin from a typed spec and would leave that out, so they are not used for it.",
  },
  // informational only: the rules of these live in code, but a designer menu / boss / HUD can sit next to them
  {
    id: "minigame", label: "a minigame or arena", test: /\b(?:mini-?games?|spleef|bed ?wars|sky ?wars|hunger games|tnt run|capture the flag|arena)\b/i, demote: [],
    text: "The rules of this game (rounds, teams, scoring, arena reset) are plugin code; designer lanes only add menus, bars or bosses around it.",
  },
];

/** The code-core archetypes a request (plus the mod it changes, when given) reads as. */
export function codeCoreFor(text: string, context = ""): CodeCore[] {
  const t = `${context}\n${text}`;
  return CODE_CORE.filter((c) => c.test.test(t));
}

/** Leave out the lanes a code-core archetype cannot use. No-op while the flag is off. */
export function applyCodeCore(needs: LaneNeed[], text: string, opts: { on?: boolean; context?: string } = {}): LaneNeed[] {
  if (!(opts.on ?? codeCoreOn())) return needs;
  const hit = codeCoreFor(text, opts.context);
  const drop = new Map<Lane, CodeCore>();
  for (const c of hit) for (const l of c.demote) if (!drop.has(l)) drop.set(l, c);
  if (!drop.size) return needs;
  return needs.map((n) => {
    const c = n.need ? drop.get(n.lane) : undefined;
    return c ? { ...n, need: false, why: "", demoted: "plain" as const, note: `${LANE_META[n.lane].label}: built as plugin code, because ${c.label} is the core of this mod.` } : n;
  });
}
