// Cyrus MEGA-PROMPT detection and AUTO-STAGING (pure, client-safe, no model, zero cost).
// Incident 2026-10-15 ("Minecraft: The Infinite Dungeon": 100 floors, 10 bosses, roguelike, instanced void world): one
// build call for the whole prompt went silent for 10-25 minutes and was killed by the 600 s wall clock, twice, with
// nothing delivered. The fix is not a bigger call, it is smaller ones: a deterministic complexity score at plan time and,
// above the threshold, an ordered STAGE list (core first, then content, then meta, then polish). Every stage is a normal
// change build (baseBuildId + changeRequest) on the previous succeeded version, so the existing requirements ledger
// (services/modbuilder/ledger.js) keeps what was built and nothing is dropped; there is no second pipeline.
// Flag CYRUS_MEGA_STAGING (off): while off, nothing in the plan response changes.
//
// Mapping to MOD_SUITES (CYRUS_MOD_SUITES, lib/cyrus/engine-core/modules.ts, flag off): a stage is a MODULE-sized unit.
// core -> kind "code", content -> "creatures" / "items" / "bosses", meta -> "menus" / "config", polish -> "config".
// `stage.modules` carries those kinds so a suite-enabled project can create its module list from the stage plan; with
// the suites flag off the stage is just a change request (this file never imports the engine core).
import type { Lane } from "./lanes";

export const MEGA_STAGING_FLAG = "CYRUS_MEGA_STAGING";
export const megaStagingOn = (env: Record<string, string | undefined> = process.env) => env[MEGA_STAGING_FLAG] === "1";

/** Score at which the plan card offers "Build this in stages" (calibrated on the 80-prompt corpus, see the CM report). */
export const MEGA_THRESHOLD = 10;
/** Score at which one build is still allowed but the hold and the warning get bigger (honest.ts). */
export const LARGE_THRESHOLD = 6.5;

type System = { id: string; label: string; re: RegExp };
/** Distinct systems a request asks for. One point each (a word list per system; a repeated word is still one system). */
export const SYSTEMS: readonly System[] = [
  { id: "world", label: "its own world", re: /\b(?:separate|instanced?|void|empty|own|private|dedicated|temporary)\b[^.]{0,30}\b(?:world|dimension)\b|\bper[- ]run (?:world|dimension)\b/i },
  { id: "run", label: "a run structure", re: /\b(?:roguelike|rogue-?lite|dungeons?|floors?|runs?|rooms?|levels?|stages?|waves?|rounds?)\b/i },
  { id: "procgen", label: "generated content", re: /\b(?:procedural\w*|randomly generated|generated rooms?|run seed|seeds?|random(?:ly)? (?:modifiers?|rooms?|events?))\b/i },
  { id: "minigame", label: "a minigame", re: /\b(?:mini-?games?|arena|lobby|spleef|teams?|last player standing|capture the flag)\b/i },
  { id: "monsters", label: "monsters", re: /\b(?:monsters?|enemies|elites?|mobs?|creatures?|minions?)\b/i },
  { id: "bosses", label: "bosses", re: /\bbosse?s?\b|\bboss ?fights?\b|\bphases?\b/i },
  { id: "items", label: "items and loot", re: /\b(?:weapons?|armou?r|trinkets?|consumables?|relics?|loot|rarit(?:y|ies)|items?)\b/i },
  { id: "economy", label: "an economy", re: /\b(?:economy|currency|coins?|money|shops?|prices?|gold|souls|spend|earn(?:ed|s)?)\b/i },
  { id: "quests", label: "quests", re: /\b(?:quests?|missions?|achievements?|objectives?|daily tasks?)\b/i },
  { id: "progression", label: "progression", re: /\b(?:progression|permanent (?:upgrades?|unlocks?|progress\w*)|unlocks?|skill tree|prestige|meta[- ]progress\w*|levels? up|experience)\b/i },
  { id: "persistence", label: "saved data", re: /\b(?:saved?|persist\w*|stored?|per[- ]player|survive restarts?|stats? screen|best floor|leaderboard)\b/i },
  { id: "hud", label: "a HUD", re: /\b(?:hud|boss ?bar|sidebar|scoreboard|action ?bar|title)\b/i },
  { id: "menus", label: "menus", re: /\b(?:menus?|gui|screens?|hub|reward screen|pick(?:s)? 1 of \d)\b/i },
  { id: "party", label: "multiplayer", re: /\b(?:parties|party|co-?op|multiplayer|per[- ]player|players? can join|friends?)\b/i },
  { id: "assets", label: "custom looks and sounds", re: /\b(?:textures?|custom models?|models?|sounds?|music|skins?)\b/i },
  { id: "admin", label: "admin tools", re: /\b(?:admin|operators?|permissions?|\/\w+ (?:help|reload|admin)|config(?:\.yml| section)?|balance)\b/i },
];

const NUMBER_WORDS: Record<string, number> = { two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10, eleven: 11, twelve: 12, fifteen: 15, twenty: 20, thirty: 30, fifty: 50, hundred: 100 };
/** "100 floors", "10 distinct bosses", "at least 8 brand new custom monsters", "twelve new items". */
const COUNT_NOUN = /\b(\d{1,4}|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|fifteen|twenty|thirty|fifty|hundred)\s+(?:[a-z-]+\s+){0,3}?(floors?|levels?|bosses|monsters|enemies|mobs|items?|weapons?|rooms?|waves?|stages?|quests?|classes|abilities|phases?|maps?|kits?|worlds?|upgrades?|modifiers?|types?|biomes?|skills?|spells?|trinkets?|armou?rs?|encounters?|recipes?|tiers?|ranks?|zones?)\b/gi;

export type MegaSignals = {
  score: number;
  /** "normal" below LARGE, "large" from LARGE (bigger hold + warning), "mega" from MEGA_THRESHOLD (stages offered). */
  level: "normal" | "large" | "mega";
  systems: { id: string; label: string }[];
  numbers: { n: number; noun: string }[];
  parts: { systems: number; numbers: number; length: number; lanes: number; commands: number };
};

/** The deterministic complexity score of a request. `laneCount` = lanes the plan builds (config not counted). */
export function megaScore(text: string, laneCount = 0): MegaSignals {
  const t = String(text ?? "");
  const systems = SYSTEMS.filter((s) => s.re.test(t)).map((s) => ({ id: s.id, label: s.label }));
  const numbers: { n: number; noun: string }[] = [];
  const seen = new Set<string>();
  for (const m of t.matchAll(COUNT_NOUN)) {
    const raw = m[1].toLowerCase();
    const n = /^\d+$/.test(raw) ? Number(raw) : NUMBER_WORDS[raw] ?? 0;
    const noun = m[2].toLowerCase().replace(/(?:es|s)$/, "");
    if (n < 5 || seen.has(noun)) continue; // "2 room types", "three waves" are small; one point per distinct counted noun
    seen.add(noun);
    numbers.push({ n, noun });
  }
  const numPts = numbers.reduce((a, x) => a + 1 + (x.n >= 50 ? 1 : 0), 0);
  const sysPts = Math.min(systems.length, 12) * 0.75;
  const lenPts = Math.min(4, Math.floor(t.length / 450));
  const lanePts = Math.max(0, laneCount - 3) * 0.75;
  const cmds = new Set((t.match(/\/[a-z][a-z0-9_-]{1,24}\b/gi) || []).map((c) => c.toLowerCase())).size;
  const cmdPts = Math.min(2, Math.max(0, cmds - 2) * 0.5);
  const score = Math.round((sysPts + numPts + lenPts + lanePts + cmdPts) * 10) / 10;
  return {
    score, level: score >= MEGA_THRESHOLD ? "mega" : score >= LARGE_THRESHOLD ? "large" : "normal",
    systems, numbers, parts: { systems: sysPts, numbers: numPts, length: lenPts, lanes: lanePts, commands: cmdPts },
  };
}

// ------------------------------------------------------------------------------------------------ stage plan
export type StageKind = "core" | "content" | "meta" | "polish";
/** MOD_SUITES module kinds (engine-core/modules.ts MODULE_KINDS) a stage maps to when the suites flag is on. */
export type StageModuleKind = "code" | "creatures" | "items" | "bosses" | "menus" | "config" | "textures";
export type StageCost = { usd: [number, number]; minutes: [number, number]; tokens: [number, number] | null; hold: number | null };
export type Stage = {
  id: string;
  title: string;
  kind: StageKind;
  /** The change request / prompt of this stage (editable by the owner; max 2,000 characters for a change). */
  text: string;
  /** The original sentences of the prompt this stage carries (the partition: every sentence is in exactly one stage). */
  clauses: string[];
  lanes: Lane[];
  modules: StageModuleKind[];
  cost: StageCost | null;
  /** The stage on its own is still large: split it (edit the list) or accept a bigger hold. */
  large: boolean;
};

/** Sentence-ish clauses of the prompt, in order; their concatenation (single spaces) is the whole text. */
export function splitClauses(text: string): string[] {
  const t = String(text ?? "").replace(/\r/g, "").trim();
  if (!t) return [];
  const out: string[] = [];
  for (const line of t.split(/\n+/)) {
    const l = line.trim();
    if (!l) continue;
    // sentence end: . ! ? followed by space + capital/digit/quote; keep "e.g." and numbers like 1.21 together
    const parts = l.split(/(?<=[.!?])\s+(?=["'(\[]?[A-Z0-9/])/);
    for (const p of parts) { const s = p.trim(); if (s) out.push(s); }
  }
  return out;
}

const RE = {
  // the substance of a run's skeleton: world handling, state, commands, floors, HUD, config, the first rooms
  coreStrong: /\b(?:existing (?:survival )?world|without touching|separate|void world|saves? (?:their|the)|saved per player|overworld|restore|put everything back|\/\w+ (?:start|leave|status|abandon|join|create|open)|floor counter|HUD|config\.yml|keep it small|more content comes later|first|for now|only two|foundation|core)\b/i,
  polish: /\b(?:final polish|polish|run seed|seeded?|admin (?:commands?|tools?)|\/\w+ help|help command|balance section|per-room modifiers?|modifiers? like|darkness|cosmetic|tweaks?|quality of life)\b/i,
  meta: /\b(?:permanent|progression|unlocks?|hub|shop menu|stats? screen|best floor|spend what|leaderboards?|prestige|skill tree|persistent upgrades?|meta)\b/i,
  monsters: /\b(?:monsters?|enemies|elites?|mobs?|creatures?|minions?|brand new custom monsters?)\b/i,
  items: /\b(?:items?|weapons?|armou?r|trinkets?|consumables?|loot|relics?|rarit(?:y|ies)|reward screen|textures?)\b/i,
  bosses: /\b(?:bosse?s?|boss ?bars?|phases?|final encounter|ending)\b/i,
};

/** Which stage a clause belongs to (priority: polish, meta, bosses, items, monsters, core strong, default core/previous). */
export function classifyClause(c: string): "core" | "monsters" | "items" | "bosses" | "meta" | "polish" | null {
  if (RE.polish.test(c)) return "polish";
  if (RE.meta.test(c) && !/\bfloor counter\b/i.test(c)) return "meta";
  if (RE.bosses.test(c) && !RE.coreStrong.test(c)) return "bosses";
  if (RE.items.test(c) && !RE.coreStrong.test(c)) return "items";
  if (RE.monsters.test(c) && !RE.coreStrong.test(c)) return "monsters";
  if (RE.coreStrong.test(c)) return "core";
  return null;
}

const TITLES: Record<"core" | "monsters" | "items" | "bosses" | "meta" | "polish", { title: string; kind: StageKind; modules: StageModuleKind[] }> = {
  core: { title: "Core: the playable skeleton", kind: "core", modules: ["code", "config"] },
  monsters: { title: "Content: monsters", kind: "content", modules: ["creatures"] },
  items: { title: "Content: items and loot", kind: "content", modules: ["items", "textures"] },
  bosses: { title: "Content: bosses", kind: "content", modules: ["bosses"] },
  meta: { title: "Meta: progression and menus", kind: "meta", modules: ["menus", "config"] },
  polish: { title: "Polish: modifiers, seed, admin", kind: "polish", modules: ["config"] },
};
const ORDER = ["core", "monsters", "items", "bosses", "meta", "polish"] as const;
export const STAGE_TEXT_MAX = 2000;
export const MAX_STAGES = 8;

const KEEP = "Keep everything already built working exactly as it is (nothing may be removed or broken). Add: ";
const CORE_TAIL = " Keep this stage small and solid: later stages add more content on top.";

export type StagePlan = { staged: boolean; level: MegaSignals["level"]; score: number; signals: MegaSignals; stages: Stage[]; reason: string };

/**
 * Split a mega prompt into ordered stages. Pure and deterministic. The clauses are PARTITIONED (each original sentence in
 * exactly one stage, in the original wording), so nothing is dropped; `coverage()` verifies that.
 * `price` fills each stage's cost (the server passes the planner's estimate; the plan card shows it). Not staged when the
 * prompt is below the threshold, or when it has nothing beyond a core (one stage).
 */
export function planStages(text: string, opts: { laneCount?: number; lanesOf?: (stageText: string) => Lane[]; price?: (stageText: string, lanes: Lane[], isChange: boolean) => StageCost | null; force?: boolean } = {}): StagePlan {
  const signals = megaScore(text, opts.laneCount ?? 0);
  const none = (reason: string): StagePlan => ({ staged: false, level: signals.level, score: signals.score, signals, stages: [], reason });
  if (!opts.force && signals.level !== "mega") return none("below the staging threshold");
  const clauses = splitClauses(text);
  if (clauses.length < 2) return none("too short to split");
  const bucket: Record<(typeof ORDER)[number], string[]> = { core: [], monsters: [], items: [], bosses: [], meta: [], polish: [] };
  // an unclassified clause follows the stage of the clause before it (a sentence that continues the previous one)
  let last: (typeof ORDER)[number] = "core";
  for (const c of clauses) {
    const k = classifyClause(c) ?? last;
    bucket[k].push(c);
    last = k;
  }
  // the first stage is always the core: when the prompt has none (every clause matched content), the first clause leads it
  if (!bucket.core.length) {
    for (const k of ORDER) if (bucket[k].length) { bucket.core.push(bucket[k].shift()!); break; }
  }
  const keys = ORDER.filter((k) => bucket[k].length);
  if (keys.length < 2) return none("one cohesive piece: build it in one go");
  const stages: Stage[] = keys.map((k, i) => {
    const body = bucket[k].join(" ");
    const isChange = i > 0;
    const textOut = (isChange ? KEEP + body : body + CORE_TAIL).slice(0, isChange ? STAGE_TEXT_MAX : 4000);
    const lanes = opts.lanesOf ? opts.lanesOf(textOut) : [];
    const sc = megaScore(body, lanes.length);
    return {
      id: `s${i + 1}-${k}`, title: TITLES[k].title, kind: TITLES[k].kind, text: textOut, clauses: bucket[k], lanes,
      modules: TITLES[k].modules, cost: opts.price ? opts.price(textOut, lanes, isChange) : null, large: sc.level !== "normal",
    };
  }).slice(0, MAX_STAGES);
  return {
    staged: true, level: signals.level, score: signals.score, signals, stages,
    reason: `${signals.systems.length} systems and ${signals.numbers.length} large counts in one request: built as ${stages.length} smaller builds, each on top of the last`,
  };
}

/** Every clause of the prompt appears in exactly one stage (the "nothing is dropped" check). */
export function coverage(text: string, stages: readonly Pick<Stage, "clauses">[]): { ok: boolean; missing: string[]; duplicated: string[] } {
  const want = splitClauses(text);
  const got = stages.flatMap((s) => s.clauses);
  const count = new Map<string, number>();
  for (const c of got) count.set(c, (count.get(c) ?? 0) + 1);
  const wantCount = new Map<string, number>();
  for (const c of want) wantCount.set(c, (wantCount.get(c) ?? 0) + 1);
  const missing = [...wantCount].filter(([c, n]) => (count.get(c) ?? 0) < n).map(([c]) => c);
  const duplicated = [...count].filter(([c, n]) => n > (wantCount.get(c) ?? 0)).map(([c]) => c);
  return { ok: !missing.length && !duplicated.length, missing, duplicated };
}

// ------------------------------------------------------------------------------------------------ chain (persisted on the build rows)
export type ChainStage = { id: string; title: string; text: string };
/** What every build of a staged run carries in cyrus.stages (lib/cyrus/meta.ts): the whole list, so edits survive reloads. */
export type StageChain = { chainId: string; /** 0-based stage this build is */ index: number; stages: ChainStage[]; /** the owner pressed "Run all stages" */ auto?: boolean };

const CHAIN_ID = /^[A-Za-z0-9_-]{6,40}$/;
const STAGE_ID = /^[A-Za-z0-9_-]{1,40}$/;
/** Validate and bound an untrusted chain (body or DB). Null = not a usable chain. */
export function parseStageChain(raw: unknown): StageChain | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  const r = raw as Record<string, unknown>;
  if (typeof r.chainId !== "string" || !CHAIN_ID.test(r.chainId)) return null;
  if (!Array.isArray(r.stages) || r.stages.length < 2 || r.stages.length > MAX_STAGES) return null;
  const stages: ChainStage[] = [];
  for (const s of r.stages) {
    if (!s || typeof s !== "object") return null;
    const o = s as Record<string, unknown>;
    if (typeof o.id !== "string" || !STAGE_ID.test(o.id) || typeof o.title !== "string" || typeof o.text !== "string") return null;
    const text = o.text.replace(/[<>]/g, " ").replace(/\s+/g, " ").trim();
    if (text.length < 12) return null;
    stages.push({ id: o.id, title: o.title.replace(/[<>\n\r]/g, " ").trim().slice(0, 80), text: text.slice(0, 4000) });
  }
  const index = typeof r.index === "number" && Number.isInteger(r.index) ? r.index : -1;
  if (index < 0 || index >= stages.length) return null;
  return { chainId: r.chainId, index, stages, ...(r.auto === true ? { auto: true } : {}) };
}

export type ChainStep =
  | { action: "run"; stage: ChainStage; index: number; auto: boolean }
  | { action: "wait"; reason: string }
  | { action: "stop"; reason: string; failedIndex: number }
  | { action: "done" };

/** What to do after the build of `chain.index` reached `status`. Failed = stop: the chain never skips past a failed stage. */
export function nextStep(chain: StageChain, status: string): ChainStep {
  if (status === "failed") return { action: "stop", reason: `Stage ${chain.index + 1} (${chain.stages[chain.index].title}) did not finish. The stages after it were not started and nothing more was held.`, failedIndex: chain.index };
  if (status !== "succeeded") return { action: "wait", reason: "the stage is still building" };
  const i = chain.index + 1;
  if (i >= chain.stages.length) return { action: "done" };
  return { action: "run", stage: chain.stages[i], index: i, auto: chain.auto === true };
}

/** The body of the next stage's change build (same shape the Forge sends for a refine). */
export function stageBuildBody(chain: StageChain, baseBuildId: string, extra: Record<string, unknown> = {}): Record<string, unknown> | null {
  const s = nextStep(chain, "succeeded");
  if (s.action !== "run") return null;
  return { baseBuildId, changeRequest: s.stage.text.slice(0, STAGE_TEXT_MAX), stageChain: { chainId: chain.chainId, index: s.index, stages: chain.stages, ...(chain.auto ? { auto: true } : {}) }, ...extra };
}

toolu_01BKpWrrdMV1S2AumsVtDNti.content:
// Cyrus MEGA-PROMPT detection and AUTO-STAGING (pure, client-safe, no model, zero cost).
// Incident 2026-10-15 ("Minecraft: The Infinite Dungeon": 100 floors, 10 bosses, roguelike, instanced void world): one
// build call for the whole prompt went silent for 10-25 minutes and was killed by the 600 s wall clock, twice, with
// nothing delivered. The fix is not a bigger call, it is smaller ones: a deterministic complexity score at plan time and,
// above the threshold, an ordered STAGE list (core first, then content, then meta, then polish). Every stage is a normal
// change build (baseBuildId + changeRequest) on the previous succeeded version, so the existing requirements ledger
// (services/modbuilder/ledger.js) keeps what was built and nothing is dropped; there is no second pipeline.
// Flag CYRUS_MEGA_STAGING (off): while off, nothing in the plan response changes.
//
// Mapping to MOD_SUITES (CYRUS_MOD_SUITES, lib/cyrus/engine-core/modules.ts, flag off): a stage is a MODULE-sized unit.
// core -> kind "code", content -> "creatures" / "items" / "bosses", meta -> "menus" / "config", polish -> "config".
// `stage.modules` carries those kinds so a suite-enabled project can create its module list from the stage plan; with
// the suites flag off the stage is just a change request (this file never imports the engine core).
import type { Lane } from "./lanes";

export const MEGA_STAGING_FLAG = "CYRUS_MEGA_STAGING";
export const megaStagingOn = (env: Record<string, string | undefined> = process.env) => env[MEGA_STAGING_FLAG] === "1";

/** Score at which the plan card offers "Build this in stages" (calibrated on the 80-prompt corpus, see the CM report). */
export const MEGA_THRESHOLD = 10;
/** Score at which one build is still allowed but the hold and the warning get bigger (honest.ts). */
export const LARGE_THRESHOLD = 6.5;

type System = { id: string; label: string; re: RegExp };
/** Distinct systems a request asks for. One point each (a word list per system; a repeated word is still one system). */
export const SYSTEMS: readonly System[] = [
  { id: "world", label: "its own world", re: /\b(?:separate|instanced?|void|empty|own|private|dedicated|temporary)\b[^.]{0,30}\b(?:world|dimension)\b|\bper[- ]run (?:world|dimension)\b/i },
  { id: "run", label: "a run structure", re: /\b(?:roguelike|rogue-?lite|dungeons?|floors?|runs?|rooms?|levels?|stages?|waves?|rounds?)\b/i },
  { id: "procgen", label: "generated content", re: /\b(?:procedural\w*|randomly generated|generated rooms?|run seed|seeds?|random(?:ly)? (?:modifiers?|rooms?|events?))\b/i },
  { id: "minigame", label: "a minigame", re: /\b(?:mini-?games?|arena|lobby|spleef|teams?|last player standing|capture the flag)\b/i },
  { id: "monsters", label: "monsters", re: /\b(?:monsters?|enemies|elites?|mobs?|creatures?|minions?)\b/i },
  { id: "bosses", label: "bosses", re: /\bbosse?s?\b|\bboss ?fights?\b|\bphases?\b/i },
  { id: "items", label: "items and loot", re: /\b(?:weapons?|armou?r|trinkets?|consumables?|relics?|loot|rarit(?:y|ies)|items?)\b/i },
  { id: "economy", label: "an economy", re: /\b(?:economy|currency|coins?|money|shops?|prices?|gold|souls|spend|earn(?:ed|s)?)\b/i },
  { id: "quests", label: "quests", re: /\b(?:quests?|missions?|achievements?|objectives?|daily tasks?)\b/i },
  { id: "progression", label: "progression", re: /\b(?:progression|permanent (?:upgrades?|unlocks?|progress\w*)|unlocks?|skill tree|prestige|meta[- ]progress\w*|levels? up|experience)\b/i },
  { id: "persistence", label: "saved data", re: /\b(?:saved?|persist\w*|stored?|per[- ]player|survive restarts?|stats? screen|best floor|leaderboard)\b/i },
  { id: "hud", label: "a HUD", re: /\b(?:hud|boss ?bar|sidebar|scoreboard|action ?bar|title)\b/i },
  { id: "menus", label: "menus", re: /\b(?:menus?|gui|screens?|hub|reward screen|pick(?:s)? 1 of \d)\b/i },
  { id: "party", label: "multiplayer", re: /\b(?:parties|party|co-?op|multiplayer|per[- ]player|players? can join|friends?)\b/i },
  { id: "assets", label: "custom looks and sounds", re: /\b(?:textures?|custom models?|models?|sounds?|music|skins?)\b/i },
  { id: "admin", label: "admin tools", re: /\b(?:admin|operators?|permissions?|\/\w+ (?:help|reload|admin)|config(?:\.yml| section)?|balance)\b/i },
];

const NUMBER_WORDS: Record<string, number> = { two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10, eleven: 11, twelve: 12, fifteen: 15, twenty: 20, thirty: 30, fifty: 50, hundred: 100 };
/** "100 floors", "10 distinct bosses", "at least 8 brand new custom monsters", "twelve new items". */
const COUNT_NOUN = /\b(\d{1,4}|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|fifteen|twenty|thirty|fifty|hundred)\s+(?:[a-z-]+\s+){0,3}?(floors?|levels?|bosses|monsters|enemies|mobs|items?|weapons?|rooms?|waves?|stages?|quests?|classes|abilities|phases?|maps?|kits?|worlds?|upgrades?|modifiers?|types?|biomes?|skills?|spells?|trinkets?|armou?rs?|encounters?|recipes?|tiers?|ranks?|zones?)\b/gi;

export type MegaSignals = {
  score: number;
  /** "normal" below LARGE, "large" from LARGE (bigger hold + warning), "mega" from MEGA_THRESHOLD (stages offered). */
  level: "normal" | "large" | "mega";
  systems: { id: string; label: string }[];
  numbers: { n: number; noun: string }[];
  parts: { systems: number; numbers: number; length: number; lanes: number; commands: number };
};

/** The deterministic complexity score of a request. `laneCount` = lanes the plan builds (config not counted). */
export function megaScore(text: string, laneCount = 0): MegaSignals {
  const t = String(text ?? "");
  const systems = SYSTEMS.filter((s) => s.re.test(t)).map((s) => ({ id: s.id, label: s.label }));
  const numbers: { n: number; noun: string }[] = [];
  const seen = new Set<string>();
  for (const m of t.matchAll(COUNT_NOUN)) {
    const raw = m[1].toLowerCase();
    const n = /^\d+$/.test(raw) ? Number(raw) : NUMBER_WORDS[raw] ?? 0;
    const noun = m[2].toLowerCase().replace(/(?:es|s)$/, "");
    if (n < 5 || seen.has(noun)) continue; // "2 room types", "three waves" are small; one point per distinct counted noun
    seen.add(noun);
    numbers.push({ n, noun });
  }
  const numPts = numbers.reduce((a, x) => a + 1 + (x.n >= 50 ? 1 : 0), 0);
  const sysPts = Math.min(systems.length, 12) * 0.75;
  const lenPts = Math.min(4, Math.floor(t.length / 450));
  const lanePts = Math.max(0, laneCount - 3) * 0.75;
  const cmds = new Set((t.match(/\/[a-z][a-z0-9_-]{1,24}\b/gi) || []).map((c) => c.toLowerCase())).size;
  const cmdPts = Math.min(2, Math.max(0, cmds - 2) * 0.5);
  const score = Math.round((sysPts + numPts + lenPts + lanePts + cmdPts) * 10) / 10;
  return {
    score, level: score >= MEGA_THRESHOLD ? "mega" : score >= LARGE_THRESHOLD ? "large" : "normal",
    systems, numbers, parts: { systems: sysPts, numbers: numPts, length: lenPts, lanes: lanePts, commands: cmdPts },
  };
}

// ------------------------------------------------------------------------------------------------ stage plan
export type StageKind = "core" | "content" | "meta" | "polish";
/** MOD_SUITES module kinds (engine-core/modules.ts MODULE_KINDS) a stage maps to when the suites flag is on. */
export type StageModuleKind = "code" | "creatures" | "items" | "bosses" | "menus" | "config" | "textures";
export type StageCost = { usd: [number, number]; minutes: [number, number]; tokens: [number, number] | null; hold: number | null };
export type Stage = {
  id: string;
  title: string;
  kind: StageKind;
  /** The change request / prompt of this stage (editable by the owner; max 2,000 characters for a change). */
  text: string;
  /** The original sentences of the prompt this stage carries (the partition: every sentence is in exactly one stage). */
  clauses: string[];
  lanes: Lane[];
  modules: StageModuleKind[];
  cost: StageCost | null;
  /** The stage on its own is still large: split it (edit the list) or accept a bigger hold. */
  large: boolean;
};

/** Sentence-ish clauses of the prompt, in order; their concatenation (single spaces) is the whole text. */
export function splitClauses(text: string): string[] {
  const t = String(text ?? "").replace(/\r/g, "").trim();
  if (!t) return [];
  const out: string[] = [];
  for (const line of t.split(/\n+/)) {
    const l = line.trim();
    if (!l) continue;
    // sentence end: . ! ? followed by space + capital/digit/quote; keep "e.g." and numbers like 1.21 together
    const parts = l.split(/(?<=[.!?])\s+(?=["'(\[]?[A-Z0-9/])/);
    for (const p of parts) { const s = p.trim(); if (s) out.push(s); }
  }
  return out;
}

const RE = {
  // the substance of a run's skeleton: world handling, state, commands, floors, HUD, config, the first rooms
  coreStrong: /\b(?:existing (?:survival )?world|without touching|separate|void world|saves? (?:their|the)|saved per player|overworld|restore|put everything back|\/\w+ (?:start|leave|status|abandon|join|create|open)|floor counter|HUD|config\.yml|keep it small|more content comes later|first|for now|only two|foundation|core)\b/i,
  polish: /\b(?:final polish|polish|run seed|seeded?|admin (?:commands?|tools?)|\/\w+ help|help command|balance section|per-room modifiers?|modifiers? like|darkness|cosmetic|tweaks?|quality of life)\b/i,
  meta: /\b(?:permanent|progression|unlocks?|hub|shop menu|stats? screen|best floor|spend what|leaderboards?|prestige|skill tree|persistent upgrades?|meta)\b/i,
  monsters: /\b(?:monsters?|enemies|elites?|mobs?|creatures?|minions?|brand new custom monsters?)\b/i,
  items: /\b(?:items?|weapons?|armou?r|trinkets?|consumables?|loot|relics?|rarit(?:y|ies)|reward screen|textures?)\b/i,
  bosses: /\b(?:bosse?s?|boss ?bars?|phases?|final encounter|ending)\b/i,
};

/** Which stage a clause belongs to (priority: polish, meta, bosses, items, monsters, core strong, default core/previous). */
export function classifyClause(c: string): "core" | "monsters" | "items" | "bosses" | "meta" | "polish" | null {
  if (RE.polish.test(c)) return "polish";
  if (RE.meta.test(c) && !/\bfloor counter\b/i.test(c)) return "meta";
  if (RE.bosses.test(c) && !RE.coreStrong.test(c)) return "bosses";
  if (RE.items.test(c) && !RE.coreStrong.test(c)) return "items";
  if (RE.monsters.test(c) && !RE.coreStrong.test(c)) return "monsters";
  if (RE.coreStrong.test(c)) return "core";
  return null;
}

const TITLES: Record<"core" | "monsters" | "items" | "bosses" | "meta" | "polish", { title: string; kind: StageKind; modules: StageModuleKind[] }> = {
  core: { title: "Core: the playable skeleton", kind: "core", modules: ["code", "config"] },
  monsters: { title: "Content: monsters", kind: "content", modules: ["creatures"] },
  items: { title: "Content: items and loot", kind: "content", modules: ["items", "textures"] },
  bosses: { title: "Content: bosses", kind: "content", modules: ["bosses"] },
  meta: { title: "Meta: progression and menus", kind: "meta", modules: ["menus", "config"] },
  polish: { title: "Polish: modifiers, seed, admin", kind: "polish", modules: ["config"] },
};
const ORDER = ["core", "monsters", "items", "bosses", "meta", "polish"] as const;
export const STAGE_TEXT_MAX = 2000;
export const MAX_STAGES = 8;

const KEEP = "Keep everything already built working exactly as it is (nothing may be removed or broken). Add: ";
const CORE_TAIL = " Keep this stage small and solid: later stages add more content on top.";

export type StagePlan = { staged: boolean; level: MegaSignals["level"]; score: number; signals: MegaSignals; stages: Stage[]; reason: string };

/**
 * Split a mega prompt into ordered stages. Pure and deterministic. The clauses are PARTITIONED (each original sentence in
 * exactly one stage, in the original wording), so nothing is dropped; `coverage()` verifies that.
 * `price` fills each stage's cost (the server passes the planner's estimate; the plan card shows it). Not staged when the
 * prompt is below the threshold, or when it has nothing beyond a core (one stage).
 */
export function planStages(text: string, opts: { laneCount?: number; lanesOf?: (stageText: string) => Lane[]; price?: (stageText: string, lanes: Lane[], isChange: boolean) => StageCost | null; force?: boolean } = {}): StagePlan {
  const signals = megaScore(text, opts.laneCount ?? 0);
  const none = (reason: string): StagePlan => ({ staged: false, level: signals.level, score: signals.score, signals, stages: [], reason });
  if (!opts.force && signals.level !== "mega") return none("below the staging threshold");
  const clauses = splitClauses(text);
  if (clauses.length < 2) return none("too short to split");
  const bucket: Record<(typeof ORDER)[number], string[]> = { core: [], monsters: [], items: [], bosses: [], meta: [], polish: [] };
  // an unclassified clause follows the stage of the clause before it (a sentence that continues the previous one)
  let last: (typeof ORDER)[number] = "core";
  for (const c of clauses) {
    const k = classifyClause(c) ?? last;
    bucket[k].push(c);
    last = k;
  }
  // the first stage is always the core: when the prompt has none (every clause matched content), the first clause leads it
  if (!bucket.core.length) {
    for (const k of ORDER) if (bucket[k].length) { bucket.core.push(bucket[k].shift()!); break; }
  }
  const keys = ORDER.filter((k) => bucket[k].length);
  if (keys.length < 2) return none("one cohesive piece: build it in one go");
  const stages: Stage[] = keys.map((k, i) => {
    const body = bucket[k].join(" ");
    const isChange = i > 0;
    const textOut = (isChange ? KEEP + body : body + CORE_TAIL).slice(0, isChange ? STAGE_TEXT_MAX : 4000);
    const lanes = opts.lanesOf ? opts.lanesOf(textOut) : [];
    const sc = megaScore(body, lanes.length);
    return {
      id: `s${i + 1}-${k}`, title: TITLES[k].title, kind: TITLES[k].kind, text: textOut, clauses: bucket[k], lanes,
      modules: TITLES[k].modules, cost: opts.price ? opts.price(textOut, lanes, isChange) : null, large: sc.level !== "normal",
    };
  }).slice(0, MAX_STAGES);
  return {
    staged: true, level: signals.level, score: signals.score, signals, stages,
    reason: `${signals.systems.length} systems and ${signals.numbers.length} large counts in one request: built as ${stages.length} smaller builds, each on top of the last`,
  };
}

/** Every clause of the prompt appears in exactly one stage (the "nothing is dropped" check). */
export function coverage(text: string, stages: readonly Pick<Stage, "clauses">[]): { ok: boolean; missing: string[]; duplicated: string[] } {
  const want = splitClauses(text);
  const got = stages.flatMap((s) => s.clauses);
  const count = new Map<string, number>();
  for (const c of got) count.set(c, (count.get(c) ?? 0) + 1);
  const wantCount = new Map<string, number>();
  for (const c of want) wantCount.set(c, (wantCount.get(c) ?? 0) + 1);
  const missing = [...wantCount].filter(([c, n]) => (count.get(c) ?? 0) < n).map(([c]) => c);
  const duplicated = [...count].filter(([c, n]) => n > (wantCount.get(c) ?? 0)).map(([c]) => c);
  return { ok: !missing.length && !duplicated.length, missing, duplicated };
}

// ------------------------------------------------------------------------------------------------ chain (persisted on the build rows)
export type ChainStage = { id: string; title: string; text: string };
/** What every build of a staged run carries in cyrus.stages (lib/cyrus/meta.ts): the whole list, so edits survive reloads. */
export type StageChain = { chainId: string; /** 0-based stage this build is */ index: number; stages: ChainStage[]; /** the owner pressed "Run all stages" */ auto?: boolean };

const CHAIN_ID = /^[A-Za-z0-9_-]{6,40}$/;
const STAGE_ID = /^[A-Za-z0-9_-]{1,40}$/;
/** Validate and bound an untrusted chain (body or DB). Null = not a usable chain. */
export function parseStageChain(raw: unknown): StageChain | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  const r = raw as Record<string, unknown>;
  if (typeof r.chainId !== "string" || !CHAIN_ID.test(r.chainId)) return null;
  if (!Array.isArray(r.stages) || r.stages.length < 2 || r.stages.length > MAX_STAGES) return null;
  const stages: ChainStage[] = [];
  for (const s of r.stages) {
    if (!s || typeof s !== "object") return null;
    const o = s as Record<string, unknown>;
    if (typeof o.id !== "string" || !STAGE_ID.test(o.id) || typeof o.title !== "string" || typeof o.text !== "string") return null;
    const text = o.text.replace(/[<>]/g, " ").replace(/\s+/g, " ").trim();
    if (text.length < 12) return null;
    stages.push({ id: o.id, title: o.title.replace(/[<>\n\r]/g, " ").trim().slice(0, 80), text: text.slice(0, 4000) });
  }
  const index = typeof r.index === "number" && Number.isInteger(r.index) ? r.index : -1;
  if (index < 0 || index >= stages.length) return null;
  return { chainId: r.chainId, index, stages, ...(r.auto === true ? { auto: true } : {}) };
}

export type ChainStep =
  | { action: "run"; stage: ChainStage; index: number; auto: boolean }
  | { action: "wait"; reason: string }
  | { action: "stop"; reason: string; failedIndex: number }
  | { action: "done" };

/** What to do after the build of `chain.index` reached `status`. Failed = stop: the chain never skips past a failed stage. */
export function nextStep(chain: StageChain, status: string): ChainStep {
  if (status === "failed") return { action: "stop", reason: `Stage ${chain.index + 1} (${chain.stages[chain.index].title}) did not finish. The stages after it were not started and nothing more was held.`, failedIndex: chain.index };
  if (status !== "succeeded") return { action: "wait", reason: "the stage is still building" };
  const i = chain.index + 1;
  if (i >= chain.stages.length) return { action: "done" };
  return { action: "run", stage: chain.stages[i], index: i, auto: chain.auto === true };
}

/** The body of the next stage's change build (same shape the Forge sends for a refine). */
export function stageBuildBody(chain: StageChain, baseBuildId: string, extra: Record<string, unknown> = {}): Record<string, unknown> | null {
  const s = nextStep(chain, "succeeded");
  if (s.action !== "run") return null;
  return { baseBuildId, changeRequest: s.stage.text.slice(0, STAGE_TEXT_MAX), stageChain: { chainId: chain.chainId, index: s.index, stages: chain.stages, ...(chain.auto ? { auto: true } : {}) }, ...extra };
}

