// Cyrus planner lane measurement over every labelled corpus, offline (no model call).
//   npx tsx scripts/cyrus/planner-measure.ts [--selector rules|eval-rules|recorded|recorded-merged] [--raw] [--fails] [--json out.json]
import fs from "node:fs";
import path from "node:path";
import { mergeNeeds, ruleNeeds } from "../../lib/cyrus/planner/rules";
import { rulesSelector } from "../../lib/cyrus/eval/lanes";
import { loadEvalSet, loadRealWorld } from "../../lib/cyrus/eval/set";
import { caseFromEvalPrompt } from "../../lib/cyrus/planner/eval";
import { measure, measureMarkdown, type Disputes, type MeasureCase } from "../../lib/cyrus/planner/measure";
import { isLane, LANES, type Lane, type LaneNeed } from "../../lib/cyrus/planner/lanes";

const args = process.argv.slice(2);
const arg = (n: string) => { const i = args.indexOf(n); return i >= 0 ? args[i + 1] : undefined; };
const selector = arg("--selector") ?? "rules";
const root = path.join(__dirname, "../..");
const lanes = (a: unknown): Lane[] => (Array.isArray(a) ? a : []).filter(isLane);

export function corpora(): Record<string, MeasureCase[]> {
  const real: MeasureCase[] = loadRealWorld().map((p) => ({ id: p.key, set: "real-world", text: p.prompt, need: lanes(p.expectLanes), plain: !p.expectLanes?.length }));
  const evalset: MeasureCase[] = loadEvalSet().flatMap((p): MeasureCase[] => {
    if (p.must_refuse) return [];
    if (p.expectLanes) return [{ id: p.key, set: "evalset", text: p.prompt, need: lanes(p.expectLanes), plain: !p.expectLanes.length }];
    const c = caseFromEvalPrompt(p);
    return c ? [{ id: c.id, set: "evalset", text: c.text, need: c.need, plain: c.plain }] : [];
  });
  const owner = JSON.parse(fs.readFileSync(path.join(root, "test/fixtures/cyrus-planner/owner-batch-labels.json"), "utf8")).prompts as (MeasureCase & { recorded: string[] })[];
  const golden = (JSON.parse(fs.readFileSync(path.join(root, "test/fixtures/cyrus-planner/golden.json"), "utf8")).prompts as { id: string; text: string; need: Lane[]; plain?: boolean }[]).map((c): Mea
  return { "real-world": real, evalset, golden, "owner-batch": owner.map((o) => ({ ...o, set: "owner-batch" })) };
}

const disputes: Disputes = args.includes("--raw") ? {} : (JSON.parse(fs.readFileSync(path.join(root, "test/fixtures/cyrus-planner/label-disputes.json"), "utf8")).disputes as Disputes);
const ownerRows = corpora()["owner-batch"] as (MeasureCase & { recorded: string[]; recordedConf: Record<string, number> })[];
const recorded = new Map<string, Lane[]>(ownerRows.map((o) => [o.id, lanes(o.recorded)]));
const recordedNeeds = (o: (typeof ownerRows)[number]): LaneNeed[] => LANES.map((l) => ({ lane: l, need: l in o.recordedConf, why: l in o.recordedConf ? "recorded" : "", confidence: o.recordedConf[l] ?
const merged = new Map<string, Lane[]>(ownerRows.map((o) => [o.id, mergeNeeds(recordedNeeds(o), o.text).lanes.filter((n) => n.need).map((n) => n.lane)]));
const select = (c: MeasureCase): Lane[] =>
  selector === "eval-rules" ? (rulesSelector({ prompt: c.text } as never) as Lane[])
    : selector === "recorded" ? (recorded.get(c.id) ?? [])
      : selector === "recorded-merged" ? (merged.get(c.id) ?? [])
      : ruleNeeds(c.text).filter((n) => n.need).map((n) => n.lane);
