// Cyrus HOLD / ESTIMATE honesty (pure, client-safe). Incident 2026-10-15: holds of 350-600 tokens were shown for builds
// that really cost $1+ ("a surprise"). The base estimate (lib/cyrus/estimate.ts, Phase 0 of 2026-10-06, 10 small builds)
// and the lane weights under-state planned builds. This layer replaces the range with MEASURED cost by class:
//
//  class  basis                                              n   usd (saka)    minutes
//  light  0-1 non-config lanes, owner batch 2026-10-14        3   0.36 - 0.55    2 - 5
//  mid    2-3 non-config lanes, owner batch                   4   0.80 - 1.15    2 - 10
//  heavy  4+ non-config lanes, owner batch                    4   0.75 - 1.30    4 - 9
//  large  mega score >= LARGE (6.5): heavy x 1.5, EXTRAPOLATED, no finished build
//  mega   mega score >= MEGA (10): 1.5 - call cap, EXTRAPOLATED; the dungeon core build timed out 3x at 600 s
//
// Source rows: test/fixtures/cyrus-planner/measured-costs.json (owner batch records.json, succeeded builds incl. guard
// and repairs; honest.test.ts re-derives the table from it). Eval journals (first1..fifth1, 497 rows) were used for the
// ordering of lane groups (plain 0.07-0.25, sound 0.29-0.5, texture 0.31-0.5, designer 0.21-0.5 p50 by class) and are
// below the portal-path numbers because they skip the guard + plan-resolved asset passes, so they are NOT used for the range.
// Flag CYRUS_HONEST_ESTIMATE (off): while off planEstimate is unchanged (and so is the hold that follows it).
import { cyrusModel, type CyrusModelId } from "../models";
import type { Lane } from "./lanes";
import { megaScore, type MegaSignals } from "./mega";

export const HONEST_FLAG = "CYRUS_HONEST_ESTIMATE";
export const honestOn = (env: Record<string, string | undefined> = process.env) => env[HONEST_FLAG] === "1";

export type CostClass = "light" | "mid" | "heavy" | "large" | "mega";
/** One build call is capped by the build service (MB_CALL_BUDGET_USD, default 2.5; the owner's spleef run died on a $1 cap). */
export const CALL_CAP_USD = 2.5;

type Row = { n: number; usd: [number, number]; minutes: [number, number]; extrapolated: boolean };
export const HONEST_TABLE: Readonly<Record<CostClass, Row>> = {
  light: { n: 3, usd: [0.36, 0.55], minutes: [2, 5], extrapolated: false },
  mid: { n: 4, usd: [0.8, 1.15], minutes: [2, 10], extrapolated: false },
  heavy: { n: 4, usd: [0.75, 1.3], minutes: [4, 9], extrapolated: false },
  large: { n: 0, usd: [1.1, 1.95], minutes: [8, 14], extrapolated: true },
  mega: { n: 0, usd: [1.5, CALL_CAP_USD], minutes: [10, 20], extrapolated: true },
};

export function costClass(nonConfigLanes: number, level: MegaSignals["level"]): CostClass {
  if (level === "mega") return "mega";
  if (level === "large") return "large";
  return nonConfigLanes >= 4 ? "heavy" : nonConfigLanes >= 2 ? "mid" : "light";
}

export type HonestEstimate = {
  klass: CostClass;
  usd: [number, number];
  /** "up to $x if it needs fixes" */
  upTo: number;
  minutes: [number, number];
  /** Measured builds behind the class (0 = extrapolated). */
  n: number;
  extrapolated: boolean;
  /** null = nothing to warn about */
  warning: string | null;
  level: MegaSignals["level"];
};

const r2 = (x: number) => Math.round(x * 100) / 100;

/** The measured range for a request on a model. Never below nothing: callers take max() with their own estimate. */
export function honestEstimate(text: string, model: CyrusModelId, lanes: readonly Lane[], opts: { change?: boolean } = {}): HonestEstimate {
  const non = lanes.filter((l) => l !== "config" && l !== "library").length;
  const sig = megaScore(text, non);
  const klass = costClass(non, sig.level);
  const row = HONEST_TABLE[klass];
  const m = cyrusModel(model);
  // measured on Saka. A refine reads the whole mod first: it is not discounted here (the base estimate discounts it by 0.8).
  const k = m.costFactor;
  const usd: [number, number] = [r2(row.usd[0] * k), r2(row.usd[1] * k)];
  const t = m.timeFactor;
  const minutes: [number, number] = [Math.max(1, Math.round(row.minutes[0] * t)), Math.max(2, Math.round(row.minutes[1] * t))];
  const upTo = r2(Math.max(usd[1] * 1.25, usd[1] + 0.25));
  let warning: string | null = null;
  if (klass === "mega") warning = `This is a very large request (${sig.systems.length} systems). One build of it can take ${minutes[0]}-${minutes[1]} minutes and cost close to the per-build limit; it can also run out of time with nothing delivered. Building it in stages is much safer.`;
  else if (klass === "large") warning = `This is a large request. It can take ${minutes[0]}-${minutes[1]} minutes and cost more than a typical build. A bigger hold is set aside; only what is used is charged.`;
  return { klass, usd, upTo, minutes, n: row.n, extrapolated: row.extrapolated, warning, level: sig.level };
}
