 * the row will get. Accounts outside the token economy (not live, not preview) pass
 * through unchanged (`tracked: false`), keeping the pre-token behaviour.
 */
export async function gateBuild(i: { user: User; buildId: string; requested: CyrusModelId | undefined; baseModel: CyrusModelId | undefined; text: string; now?: Date;
  /** Live-test fix (C2): "Auto" = the cheapest capable model for the request and its planned lanes (lib/cyrus/planner/estimate.ts autoModel). */
  auto?: boolean;
  /** Live-test fix (C1): the lanes this build really builds; the hold follows their estimate (holdRange). */
  lanes?: readonly Lane[];
  change?: boolean;
  /** Cyrus starter bank: a ready-made build (no model call). Holds and charges the flat cyrus_tok_bank_charge, any plan. */
  bank?: boolean }): Promise<BuildGate> {
  const cfg = await loadTokenConfig();
  // Defence in depth for the launch pair (lib/cyrus/launch-state.ts): a build that reaches here with the token economy
  // not active for this account must not run unmetered. Private-preview accounts are always "active", so this only
  // ever refuses a public account while cyrus_studio_public_enabled is on and cyrus_tok_live is off.
  if (!(await tokensActiveFor(i.user, cfg))) return { ok: false, status: 403, code: "launch_pair", model: i.requested ?? i.baseModel, error: "Cyrus building isn't open yet." };
  const now = i.now ?? new Date();
  await ensureStarterTokens(i.user, cfg);
  const tier = await tierOf(i.user.id, cfg, now);
  let model: CyrusModelId = i.requested ?? (i.auto ? autoModel(i.text, i.lanes ?? [], modelsFor(tier)) : i.baseModel ?? defaultModelFor(tier));
  // A change to a version built on a locked model falls back to the best allowed one
  // unless the customer explicitly asked for the locked model.
  if (!i.requested && !canUseModel(tier, model)) model = defaultModelFor(tier);
  if (i.bank) model = defaultModelFor(tier); // no model runs; the reservation row still names the plan's default
  if (cfg.enforce && !i.bank && !canUseModel(tier, model)) {
    const need = tierForModel(model);
    return { ok: false, status: 403, code: "model_locked", model, tier, error: `${cyrusModel(model).name} unlocks with the ${TIER_LABEL[need]} plan. Get tokens to unlock it, or pick ${tier === "free" || tier === "katara" ? "Katara
  }
  const range: [number, number] = i.bank ? [cfg.bankCharge, cfg.bankCharge] : holdRange(model, complexityOf(i.text), cfg, i.lanes ? planEstimate(i.text, model, i.lanes, { change: i.change }).usd : undefined);
  const r = await reserveTokens({
    userId: i.user.id, buildId: i.buildId, model, need: range[0], now,
    pick: (available) => reserveAmount(available, range),
    dailyCap: () => dailyCapFor(i.user.createdAt, now, cfg),
    allowShort: !cfg.enforce,
